import { createMaterialSignedUpload } from "@/actions/classroom-materials";
import { createClient as createBrowserSupabase } from "@/lib/supabase/client";
import { CLASSROOM_MATERIALS_BUCKET } from "@/lib/storage/classroom-bucket";

/**
 * Uploads a file directly from the browser to Supabase Storage using a short-lived
 * signed upload session generated by a Server Action, bypassing Vercel's 4.5 MB limit.
 */
export async function uploadClassroomFileWithSignedUrl(
  companyId: string,
  file: File,
  prefix?: string
): Promise<{ publicUrl: string; size: number; type: string; name: string }> {
  const contentType = file.type || "application/octet-stream";
  const session = await createMaterialSignedUpload(companyId, file.name, prefix);
  const browserSupabase = createBrowserSupabase();

  const { error } = await browserSupabase.storage
    .from(CLASSROOM_MATERIALS_BUCKET)
    .uploadToSignedUrl(session.path, session.token, file, {
      contentType,
    });

  if (error) {
    throw new Error(error.message);
  }

  return {
    publicUrl: session.publicUrl,
    size: file.size,
    type: contentType,
    name: file.name,
  };
}
